using System.Windows;using System.Windows.Controls;using DirectorFamilyTravelDesk.Models;namespace DirectorFamilyTravelDesk.Views;public partial class CitiesView:UserControl,IRefreshable{private long _id;public CitiesView(){InitializeComponent();}public void RefreshData(){Grid.ItemsSource=App.Repository.GetCities(false);}private void Grid_SelectionChanged(object s,SelectionChangedEventArgs e){if(Grid.SelectedItem is CityItem x){_id=x.Id;NameBox.Text=x.Name;IataBox.Text=x.Iata;ActiveBox.IsChecked=x.IsActive;}}private void Save_Click(object s,RoutedEventArgs e){if(string.IsNullOrWhiteSpace(NameBox.Text)||IataBox.Text.Trim().Length!=3){MessageBox.Show("Enter City and 3-letter IATA code.");return;}try{App.Repository.SaveCity(new(){Id=_id,Name=NameBox.Text,Iata=IataBox.Text,IsActive=ActiveBox.IsChecked==true});_id=0;NameBox.Text=IataBox.Text="";ActiveBox.IsChecked=true;RefreshData();}catch(Exception ex){MessageBox.Show(ex.Message);}}}